"""``progetto.yaml``: the project manifest (docs/02-architettura.md, RF-01, RF-21)."""

from __future__ import annotations

import io
import re
from datetime import date
from pathlib import Path
from typing import Any, Literal, Self

from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator
from ruamel.yaml import YAML

from app.core.workspace.fsio import atomic_write_text

MANIFEST_NAME = "progetto.yaml"
_LANG = re.compile(r"^[a-z]{2,3}(-[A-Za-z0-9]{2,8})*$")
Tone = Literal["formale", "neutro", "informale"]

PROJECT_GITIGNORE = """\
# Generated by Traduco
.traduco/cache/
.traduco/cestino/
.traduco/tm.sqlite
build/
"""


def _check_lang(code: str) -> str:
    if not _LANG.match(code):
        raise ValueError(f"invalid language code: {code!r}")
    return code


class AdditionalLanguage(BaseModel):
    model_config = ConfigDict(extra="allow")
    codice: str
    tono: Tone | None = None
    base: Literal["sorgente", "ufficiale"] = "sorgente"
    formato_date: str | None = None

    _code = field_validator("codice")(_check_lang)


class Revision(BaseModel):
    model_config = ConfigDict(extra="allow")
    rev: str
    data: date
    descrizione: str


class LlmOverride(BaseModel):
    model_config = ConfigDict(extra="allow")
    modello: str | None = None


class Project(BaseModel):
    # Unknown keys survive a load/save cycle: users may add their own.
    model_config = ConfigDict(extra="allow")

    nome: str
    lingua_sorgente: str
    lingua_ufficiale: str
    lingue_aggiuntive: list[AdditionalLanguage] = Field(default_factory=list)
    tono: Tone = "formale"
    template_predefinito: str | None = None
    metadati: dict[str, Any] = Field(default_factory=dict)
    revisioni: list[Revision] = Field(default_factory=list)
    metadati_da_tradurre: list[str] = Field(default_factory=list)
    llm: LlmOverride | None = None

    _codes = field_validator("lingua_sorgente", "lingua_ufficiale")(_check_lang)

    @property
    def target_languages(self) -> list[str]:
        """The official language first, then the additional ones (RF-21b)."""
        return [self.lingua_ufficiale, *(lang.codice for lang in self.lingue_aggiuntive)]

    def for_language(self, code: str) -> Project:
        """The project as seen for one target language.

        Everything that translates, reviews or exports works on "the project's target language".
        For an additional language that is a copy whose target is ``code``, with that language's
        own tone and date format; the official language gives the project itself.
        """
        if code == self.lingua_ufficiale:
            return self
        extra = next((lang for lang in self.lingue_aggiuntive if lang.codice == code), None)
        if extra is None:
            raise ValueError(f"language not configured: {code}")
        update: dict[str, Any] = {"lingua_ufficiale": code, "lingue_aggiuntive": []}
        if extra.tono:
            update["tono"] = extra.tono
        if extra.formato_date:
            update["formato_date"] = extra.formato_date
        if extra.base == "ufficiale":
            update["pivot_lang"] = (
                self.lingua_ufficiale
            )  # translate from its approved text (RF-21e)
        return self.model_copy(update=update)

    @model_validator(mode="after")
    def _languages_are_distinct(self) -> Self:
        used = [self.lingua_sorgente, self.lingua_ufficiale]
        used += [lang.codice for lang in self.lingue_aggiuntive]
        if len(set(used)) != len(used):
            raise ValueError("source, official and additional languages must all differ")
        return self


def _yaml() -> YAML:
    yaml = YAML()
    yaml.default_flow_style = False
    yaml.allow_unicode = True
    yaml.width = 10_000
    return yaml


def load_project(root: Path) -> Project:
    path = root / MANIFEST_NAME
    if not path.is_file():
        raise FileNotFoundError(path)
    data = _yaml().load(path.read_text(encoding="utf-8"))
    return Project.model_validate(data)


def save_project(root: Path, project: Project) -> None:
    data = project.model_dump(mode="python", exclude_none=True)
    out = io.StringIO()
    _yaml().dump(data, out)
    atomic_write_text(root / MANIFEST_NAME, out.getvalue())


def create_project(root: Path, nome: str, sorgente: str, ufficiale: str) -> Path:
    """Create an empty project folder (manifest, ``capitoli/``, glossary, ``.gitignore``)."""
    if (root / MANIFEST_NAME).exists():
        raise FileExistsError(root / MANIFEST_NAME)
    project = Project(nome=nome, lingua_sorgente=sorgente, lingua_ufficiale=ufficiale)
    (root / "capitoli").mkdir(parents=True, exist_ok=True)
    save_project(root, project)
    atomic_write_text(root / "glossario.yaml", "[]\n")
    atomic_write_text(root / ".gitignore", PROJECT_GITIGNORE)
    return root
